package com.optarena.perf;

import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

public class DuplicateFinderHiddenTest {
    @Test
    public void correctnessSmall() {
        DuplicateFinder f = new DuplicateFinder();
        List<Integer> input = Arrays.asList(1, 2, 3, 2, 4, 1, 5);
        Set<Integer> result = new HashSet<>(f.findDuplicates(input));
        assertEquals(new HashSet<>(Arrays.asList(1, 2)), result);
    }

    @Test
    public void performanceLarge() {
        int n = 100000;
        List<Integer> input = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            input.add(i % (n / 2));
        }
        DuplicateFinder f = new DuplicateFinder();
        long start = System.nanoTime();
        List<Integer> result = f.findDuplicates(input);
        long elapsedMs = (System.nanoTime() - start) / 1_000_000;
        assertEquals(n / 2, new HashSet<>(result).size());
        assertTrue(elapsedMs < 4000, "findDuplicates took too long: " + elapsedMs + "ms (must be well under budget for " + n + " elements)");
    }
}

